new_render = '''def render_inner_html(md: Markdown, elem: etree.Element) -> str:
    """Serialize the inner HTML of an element (text + children, not the element itself).

    Unlike ElementTree's serializer, this builds the string directly to avoid
    escaping raw HTML blocks that were stashed during parsing.
    """
    def resolve_stash(text):
        if text is None:
            return ''
        def _html_sub(m):
            try:
                raw = md.htmlStash.rawHtmlBlocks[int(m.group(1))]
            except (IndexError, TypeError):
                return m.group(0)
            return raw
        return HTML_PLACEHOLDER_RE.sub(_html_sub, text)

    parts = []
    # Text content before any children
    parts.append(resolve_stash(elem.text))
    # Children and their tails
    for child in elem:
        # Skip footnote reference <sup> elements to prevent their text from leaking into TOC names
        if child.tag == 'sup' and 'fnref' in child.get('id', ''):
            continue
        parts.append(md.serializer(child))
        parts.append(resolve_stash(child.tail))
    return ''.join(parts)'''

